// Route input from webhook or chat trigger
const body = $input.item.json.body || $input.item.json;

// Handle chat_delegation from orchestration bridge
if (body.action === 'chat_delegation' && body.context) {
  const ctx = body.context;
  const history = (ctx.conversation_history || [])
    .map(m => `[${m.role}]: ${(m.content || '').substring(0, 300)}`)
    .join('\n');

  const chatInput = `[CHAT DELEGATION] Uživatel napsal v AI chatu a systém tě žádá o reakci jako Aisha Dirigent.\n\nUživatelova zpráva: "${ctx.user_message}"\nOdpověď asistenta: "${(ctx.assistant_response || '').substring(0, 500)}"\nKategorie: ${ctx.category || 'general'}\nEskalační signály: ${(ctx.escalation_signals || []).join(', ') || 'žádné'}\nJazyk: ${ctx.language || 'cs'}${history ? '\n\nHistorie konverzace:\n' + history : ''}\n\nJako Aisha Dirigent se rozhodni: máš co hodnotného přidat? Pokud ano, odpověz stručně v jazyce uživatele. Pokud ne, odpověz prázdným řetězcem.`;

  return {
    json: {
      chatInput,
      session_id: 'chat-delegation-' + (ctx.conversation_id || Date.now()),
      source: 'chat_delegation',
      metadata: {
        user_id: ctx.user_id,
        conversation_id: ctx.conversation_id,
        category: ctx.category,
        escalation_signals: ctx.escalation_signals,
      },
      _delegation: true,
    }
  };
}

const chatInput = body.chatInput || body.query || body.message || body.text || body.action || '';

return {
  json: {
    chatInput,
    session_id: body.session_id || body.sessionId || 'dirigent-' + Date.now(),
    source: body.source || 'webhook',
    metadata: {
      user_id: body.user_id,
      story_id: body.story_id,
      pr_number: body.pr_number,
    }
  }
};

// Format Dirigent response for API consumers
const agentOutput = $input.item.json;
const rawOutput = agentOutput.output || agentOutput.text || '';

// Check if this was a chat delegation request
const prepareData = $('Prepare Webhook Input').first()?.json || {};
const isDelegation = prepareData._delegation === true;

let action = 'comment';
if (isDelegation) {
  const text = typeof rawOutput === 'string' ? rawOutput : '';
  if (!text || text.trim().length === 0) {
    action = 'silent';
  } else if (/\[(eskal|escalat)/i.test(text)) {
    action = 'escalate';
  } else if (/\[(override|přepiš)/i.test(text)) {
    action = 'override';
  }
}

const content = typeof rawOutput === 'string' ? rawOutput : JSON.stringify(rawOutput);

return {
  json: {
    success: true,
    agent: 'dirigent',
    content: content,
    response: content,
    action: action,
    timestamp: new Date().toISOString()
  }
};

